CREATE TABLE IF NOT EXISTS TB_EEP_LAB_RESEARCHER_M ( RSCH_SQ int NOT NULL AUTO_INCREMENT , STAFF_SQ int NOT NULL , ROLE_CD varchar(10) NOT NULL COMMENT 'HEAD 연구소장, MEMBER 연구원' , START_DT date NOT NULL COMMENT '소속 시작일' , END_DT date NULL COMMENT '소속 종료일' , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (RSCH_SQ) , KEY IX_LAB_RSCH_STAFF (STAFF_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='연구소 연구원 소속 기간';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_PROJECT_M ( PRJ_SQ int NOT NULL AUTO_INCREMENT , PRJ_NM varchar(200) NOT NULL , START_DT date NOT NULL , END_DT date NOT NULL , PLACE varchar(200) NOT NULL , MANAGER_EMPLY_ID varchar(50) NOT NULL COMMENT '결재자: 부서장 계정' , CEO_EMPLY_ID varchar(50) NOT NULL COMMENT '결재자: 대표 계정' , DRIVE_FOLDER_ID varchar(100) NOT NULL COMMENT '드라이브 과제 폴더 ID' , UPDT_EMPLY_ID varchar(50) NULL , UPDT_DT datetime NULL , PRIMARY KEY (PRJ_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='연구과제';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_JOURNAL_M ( JRN_SQ int NOT NULL AUTO_INCREMENT , PRJ_SQ int NOT NULL , YM char(7) NOT NULL COMMENT '대상 월 yyyy-MM' , CONTENT mediumtext NULL , STATUS_CD varchar(12) NOT NULL COMMENT 'DRAFT, SUBMITTED, MANAGER_OK, CEO_OK' , WRITER_EMPLY_ID varchar(50) NOT NULL , WRITER_NM varchar(100) NULL , SNAP_PRJ_NM varchar(200) NULL COMMENT '제출 시점 과제명 (이후 과제를 고쳐도 일지는 그대로)' , SNAP_PLACE varchar(200) NULL , SNAP_PERIOD varchar(30) NULL , SNAP_MEMBERS varchar(2000) NULL COMMENT '제출 시점 연구인원' , PDF_FILE_ID varchar(100) NULL , PDF_LINK varchar(500) NULL , UPLOAD_ERR varchar(300) NULL , PRIMARY KEY (JRN_SQ) , UNIQUE KEY UX_LAB_JOURNAL_MONTH (PRJ_SQ, YM) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='월간 연구일지';
CREATE TABLE IF NOT EXISTS TB_EEP_LAB_JOURNAL_H ( HIS_SQ int NOT NULL AUTO_INCREMENT , JRN_SQ int NOT NULL , ACTION_CD varchar(20) NOT NULL , STATUS_CD varchar(12) NOT NULL COMMENT '처리 후 상태' , ACTOR_ID varchar(50) NOT NULL , ACTOR_NM varchar(100) NULL , NOTE varchar(1000) NULL , REG_DT datetime NOT NULL COMMENT 'KST' , PRIMARY KEY (HIS_SQ) , KEY IX_LAB_HIS_JOURNAL (JRN_SQ) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='월간 연구일지 처리 이력';

mapper.select:
SELECT COUNT(*) FROM TB_EEP_LAB_RESEARCHER_M
WHERE STAFF_SQ = #{STAFF_SQ} AND RSCH_SQ <> #{RSCH_SQ}
  AND START_DT <= IFNULL(NULLIF(#{END_DT}, ''), '9999-12-31')
  AND IFNULL(END_DT, '9999-12-31') >= #{START_DT}

mapper.update:
UPDATE TB_EEP_LAB_RESEARCHER_M
SET STAFF_SQ = #{STAFF_SQ}, ROLE_CD = #{ROLE_CD}, START_DT = #{START_DT}, END_DT = NULLIF(#{END_DT}, ''), UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE RSCH_SQ = #{RSCH_SQ}

UPDATE TB_EEP_LAB_PROJECT_M
SET PRJ_NM = #{PRJ_NM}, START_DT = #{START_DT}, END_DT = #{END_DT}, PLACE = #{PLACE}, MANAGER_EMPLY_ID = #{MANAGER_EMPLY_ID}
	, CEO_EMPLY_ID = #{CEO_EMPLY_ID}, DRIVE_FOLDER_ID = #{DRIVE_FOLDER_ID}, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE PRJ_SQ = #{PRJ_SQ}

UPDATE TB_EEP_LAB_JOURNAL_M
SET STATUS_CD = #{TO}
	, SNAP_PRJ_NM = NULL, SNAP_PLACE = NULL, SNAP_PERIOD = NULL, SNAP_MEMBERS = NULL
WHERE JRN_SQ = #{JRN_SQ} AND STATUS_CD = #{FROM}
